WITH cleaned AS (SELECT *, DATE_FORMAT(delivered_date, 'MMM yyyy') delivered_date_label, COALESCE(carrier, 'N/A') resolved_carrier FROM shipments WHERE carrier = 'FedEx') SELECT dim.channel, s.status AS shipment_status, COUNT(*) AS cnt, ROUND(AVG(s.cost), 2) AS avg_cost FROM cleaned s INNER JOIN orders dim ON s.order_id = dim.id GROUP BY ROLLUP (dim.channel, s.status) ORDER BY avg_cost DESC
